PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS continuum_economy_accounts(account_id TEXT PRIMARY KEY,balance INTEGER NOT NULL DEFAULT 0,account_type INTEGER NOT NULL DEFAULT 0,created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS continuum_economy_operations(operation_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,operation_kind INTEGER NOT NULL,created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS continuum_economy_transactions(transaction_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,sender_id TEXT NOT NULL,receiver_id TEXT NOT NULL,amount INTEGER NOT NULL,transaction_type INTEGER NOT NULL,region_id TEXT NOT NULL,object_id TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status INTEGER NOT NULL,sender_balance INTEGER NOT NULL,receiver_balance INTEGER NOT NULL,failure_reason TEXT NOT NULL DEFAULT '',created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_continuum_economy_sender_time ON continuum_economy_transactions(sender_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_receiver_time ON continuum_economy_transactions(receiver_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_type_time ON continuum_economy_transactions(transaction_type,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_adjustments(operation_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,account_id TEXT NOT NULL,actor_id TEXT NOT NULL,amount INTEGER NOT NULL,adjustment_kind INTEGER NOT NULL,transaction_type INTEGER NOT NULL,reason TEXT NOT NULL,status INTEGER NOT NULL,resulting_balance INTEGER NOT NULL,failure_reason TEXT NOT NULL DEFAULT '',created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_continuum_economy_adjustment_account_time ON continuum_economy_adjustments(account_id,created_utc);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_adjustment_actor_time ON continuum_economy_adjustments(actor_id,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_purchases(purchase_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,buyer_id TEXT NOT NULL,seller_id TEXT NOT NULL,amount INTEGER NOT NULL,transaction_type INTEGER NOT NULL,region_id TEXT NOT NULL,object_id TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',state INTEGER NOT NULL,buyer_balance INTEGER NOT NULL,seller_balance INTEGER NOT NULL,failure_reason TEXT NOT NULL DEFAULT '',created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),completed_utc TEXT NULL);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_purchase_buyer_state ON continuum_economy_purchases(buyer_id,state);
CREATE INDEX IF NOT EXISTS idx_continuum_economy_purchase_seller_time ON continuum_economy_purchases(seller_id,created_utc);
CREATE TABLE IF NOT EXISTS continuum_economy_account_registrations(operation_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,account_id TEXT NOT NULL,actor_id TEXT NOT NULL,account_type INTEGER NOT NULL,display_name TEXT NOT NULL,created_utc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_continuum_economy_registration_account ON continuum_economy_account_registrations(account_id);
